  if($('#indicatorNotifyBtn'))$('#indicatorNotifyBtn').onclick=async()=>{if(!('Notification'in window))return alert('此瀏覽器不支援通知');const p=await Notification.requestPermission();alert(p==='granted'?'通知已啟用':'通知未啟用')};
